"use client";

import * as CollapsiblePrimitive from "@radix-ui/react-collapsible";
import * as React from "react";
import { cn } from "../../lib/utils.js";

/**
 * Lifecycle of a Task step. Mirrors `@hex-core/components`'
 * `ToolCallState` exactly — kept inline (rather than imported from
 * `../types.js`) so the registry CLI distribution path (`npx hex add
 * task`) ships a self-contained file. ToolCall has the same enum
 * imported from `../types.js` for backwards-compat with its earlier
 * shape; new consumers should treat the two unions as one vocabulary.
 */
type ToolCallState = "pending" | "running" | "result" | "error";

/**
 * Multi-step task progress for an AI workflow.
 *
 * Each step's `state` re-uses the canonical `ToolCallState` enum
 * (`pending` / `running` / `result` / `error`) so the vocabulary stays
 * consistent across the AI surface. The header tracks aggregate
 * progress ("3 of 5 steps", or "Done in X.Xs" once `durationMs` is
 * set).
 *
 * Composes well with `<Reasoning>` for in-step thinking traces and
 * `<ToolCall>` for individual tool invocations.
 *
 * @example
 * <Task
 *   label="Refactoring auth"
 *   steps={[
 *     { id: "read", label: "Read existing auth", state: "result" },
 *     { id: "write", label: "Apply changes", state: "running" },
 *     { id: "test", label: "Run tests", state: "pending" },
 *   ]}
 *   durationMs={12_400}
 * />
 */
export interface TaskProps {
	/** Optional title shown above the step list. Skipped if absent. */
	label?: string;
	/** Ordered list of steps. Each carries an id, label, and state. */
	steps: TaskStep[];
	/** Time spent on the task in milliseconds. Renders "Done in X.Xs" when set. */
	durationMs?: number;
	/** Whether the step list is expanded by default. */
	defaultOpen?: boolean;
	className?: string;
}

/** A single row in a Task. */
export interface TaskStep {
	/** Stable identifier — used for the React key and any consumer tracking. */
	id: string;
	/** Human-readable step label. */
	label: string;
	/** Lifecycle status — same vocabulary as `<ToolCall>`'s `state`. */
	state: ToolCallState;
	/** Optional detail line shown beneath the label. */
	detail?: string;
}

/**
 * Render a multi-step task progress card.
 * @param props - The task label, steps, and optional duration.
 * @returns A Collapsible wrapping a step list.
 */
function Task({ label, steps, durationMs, defaultOpen = true, className }: TaskProps) {
	const summary = summarize(steps, durationMs);

	return (
		<CollapsiblePrimitive.Root
			defaultOpen={defaultOpen}
			className={cn(
				"overflow-hidden rounded-md border border-border bg-card text-card-foreground",
				className,
			)}
		>
			<CollapsiblePrimitive.Trigger
				className={cn(
					"group flex w-full items-center gap-2 px-3 py-2 text-left",
					"transition-all duration-[var(--duration-normal,200ms)] ease-out",
					"hover:bg-muted/30",
					"focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
				)}
			>
				<div className="flex min-w-0 flex-col gap-0.5">
					{label ? (
						<span className="text-sm font-medium text-foreground">{label}</span>
					) : null}
					<span className="text-xs text-muted-foreground">{summary}</span>
				</div>
				<Chevron />
			</CollapsiblePrimitive.Trigger>
			<CollapsiblePrimitive.Content className="overflow-hidden border-t border-foreground/[0.06]">
				<ol className="my-0 ml-0 flex list-none flex-col pl-0">
					{steps.map((step) => (
						<li
							key={step.id}
							className="flex items-start gap-3 px-3 py-2 text-sm before:content-none last:pb-3"
						>
							<StepIcon state={step.state} />
							<div className="flex min-w-0 flex-col gap-0.5">
								<span
									className={cn(
										"leading-snug",
										step.state === "result" && "text-muted-foreground line-through decoration-muted-foreground/50",
										step.state === "running" && "text-foreground font-medium",
										step.state === "error" && "text-destructive",
										step.state === "pending" && "text-muted-foreground",
									)}
								>
									{step.label}
								</span>
								{step.detail ? (
									<span className="text-xs text-muted-foreground">{step.detail}</span>
								) : null}
							</div>
						</li>
					))}
				</ol>
			</CollapsiblePrimitive.Content>
		</CollapsiblePrimitive.Root>
	);
}

function summarize(steps: TaskStep[], durationMs: number | undefined): string {
	const total = steps.length;
	const done = steps.filter((s) => s.state === "result").length;
	const running = steps.some((s) => s.state === "running");
	const errored = steps.some((s) => s.state === "error");
	if (errored) return `${done} of ${total} steps · failed`;
	if (running) return `${done} of ${total} steps`;
	if (done === total && total > 0 && typeof durationMs === "number") {
		return `Done in ${formatDuration(durationMs)}`;
	}
	if (done === total && total > 0) return "Done";
	return `${done} of ${total} steps`;
}

function formatDuration(ms: number): string {
	if (ms < 1000) return `${ms}ms`;
	const seconds = ms / 1000;
	const formatted = seconds >= 10 ? Math.round(seconds).toString() : seconds.toFixed(1);
	return `${formatted}s`;
}

function StepIcon({ state }: { state: ToolCallState }) {
	const cls = "mt-0.5 shrink-0";
	if (state === "result") {
		return (
			<svg
				aria-label="Done"
				role="img"
				viewBox="0 0 16 16"
				width="14"
				height="14"
				fill="none"
				stroke="currentColor"
				strokeWidth="2"
				strokeLinecap="round"
				strokeLinejoin="round"
				className={cn(cls, "text-emerald-500")}
			>
				<circle cx="8" cy="8" r="6" />
				<path d="M5 8.25l2.25 2.25L11 6" />
			</svg>
		);
	}
	if (state === "running") {
		return (
			<svg
				aria-label="Running"
				role="img"
				viewBox="0 0 16 16"
				width="14"
				height="14"
				fill="none"
				stroke="currentColor"
				strokeWidth="2"
				strokeLinecap="round"
				className={cn(cls, "text-primary motion-safe:animate-spin")}
			>
				<path d="M8 1.5a6.5 6.5 0 1 1-6.5 6.5" />
			</svg>
		);
	}
	if (state === "error") {
		return (
			<svg
				aria-label="Error"
				role="img"
				viewBox="0 0 16 16"
				width="14"
				height="14"
				fill="none"
				stroke="currentColor"
				strokeWidth="2"
				strokeLinecap="round"
				strokeLinejoin="round"
				className={cn(cls, "text-destructive")}
			>
				<circle cx="8" cy="8" r="6" />
				<path d="M5 5l6 6M11 5l-6 6" />
			</svg>
		);
	}
	// pending
	return (
		<svg
			aria-label="Pending"
			role="img"
			viewBox="0 0 16 16"
			width="14"
			height="14"
			fill="none"
			stroke="currentColor"
			strokeWidth="2"
			className={cn(cls, "text-muted-foreground")}
		>
			<circle cx="8" cy="8" r="6" strokeDasharray="2 2" />
		</svg>
	);
}

function Chevron() {
	return (
		<svg
			aria-hidden
			viewBox="0 0 16 16"
			width="12"
			height="12"
			fill="none"
			stroke="currentColor"
			strokeWidth="1.5"
			strokeLinecap="round"
			strokeLinejoin="round"
			className="ml-auto shrink-0 text-muted-foreground transition-transform duration-200 group-data-[state=open]:rotate-180"
		>
			<path d="M4 6l4 4 4-4" />
		</svg>
	);
}

export { Task };

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex UI: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

